    html: "<h1 class=\"chapter-title\">16. APPENDIX</h1>\n        <p style=\"font-weight:bold; margin-bottom:8px; font-size:11pt;\">SOURCE CODE: CenteredUploadDropzone.tsx (Part 1 - Component Setup & Drag Events):</p>\n        <pre class=\"code-box\"><code>import React, { useState, useRef, DragEvent } from &#039;react&#039;;\nimport { \n  Upload, \n  AlertCircle, \n  Loader2, \n  CheckCircle2, \n  Files,\n  Sparkles,\n  ArrowRight\n} from &#039;lucide-react&#039;;\nimport { processDocumentUpload } from &#039;../services/ocrEngine&#039;;\nimport { DocumentItem } from &#039;../types/document&#039;;\n\ninterface CenteredUploadDropzoneProps {\n  onDocumentProcessed: (doc: DocumentItem) =&gt; void;\n  onOpenDocumentsList: () =&gt; void;\n  totalDocuments: number;\n}\n\nexport const CenteredUploadDropzone: React.FC&lt;CenteredUploadDropzoneProps&gt; = ({\n  onDocumentProcessed,\n  onOpenDocumentsList,\n  totalDocuments\n}) =&gt; {\n  const [isDragging, setIsDragging] = useState(false);\n  const [isProcessing, setIsProcessing] = useState(false);\n  const [currentPhase, setCurrentPhase] = useState(&#039;&#039;);\n  const [progress, setProgress] = useState(0);\n  const [error, setError] = useState&lt;string | null&gt;(null);\n  const [lastUploadedDoc, setLastUploadedDoc] = useState&lt;DocumentItem | null&gt;(null);\n  const fileInputRef = useRef&lt;HTMLInputElement&gt;(null);\n\n  const handleFiles = async (files: FileList | null) =&gt; {\n    if (!files || files.length === 0) return;\n    const file = files[0];\n\n    setIsProcessing(true);\n    setError(null);\n    setLastUploadedDoc(null);\n    setCurrentPhase(&#039;Preparing document upload...&#039;);\n    setProgress(5);\n\n    try {\n      const processedDoc = await processDocumentUpload(file, {\n        onPhaseChange: (phase, pct) =&gt; {\n          setCurrentPhase(phase);\n          setProgress(pct);\n        }\n      });\n\n</code></pre>"
