    html: "<p style=\"font-weight:bold; margin-bottom:8px; font-size:11pt;\">SOURCE CODE: DocumentTableView.tsx (Part 1 - Header & Search Integration):</p>\n        <pre class=\"code-box\"><code>import React from &#039;react&#039;;\nimport { \n  FileText, \n  Trash2, \n  ExternalLink, \n  Download, \n  ChevronRight,\n  ChevronDown,\n  CheckSquare,\n  Square,\n  Search\n} from &#039;lucide-react&#039;;\nimport { DocumentItem, SearchMatch } from &#039;../types/document&#039;;\nimport { highlightText } from &#039;../utils/searchHighlight&#039;;\n\ninterface DocumentTableViewProps {\n  documents: DocumentItem[];\n  searchResults: SearchMatch[];\n  searchQuery: string;\n  selectedDocIds: string[];\n  onToggleSelect: (id: string) =&gt; void;\n  onSelectAll: () =&gt; void;\n  onInspectDocument: (doc: DocumentItem) =&gt; void;\n  onDeleteDocument: (id: string) =&gt; void;\n  onTagClick: (tag: string) =&gt; void;\n}\n\nexport const DocumentTableView: React.FC&lt;DocumentTableViewProps&gt; = ({\n  documents,\n  searchResults,\n  searchQuery,\n  selectedDocIds,\n  onToggleSelect,\n  onSelectAll,\n  onInspectDocument,\n  onDeleteDocument,\n  onTagClick\n}) =&gt; {\n  const allSelected = documents.length &gt; 0 &amp;&amp; selectedDocIds.length === documents.length;\n\n  const formatFileSize = (bytes: number) =&gt; {\n    if (bytes &lt; 1024) return `${bytes} B`;\n    if (bytes &lt; 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;\n    return `${(bytes / (1024 * 1024)).toFixed(2)} MB`;\n  };\n\n  const formatDate = (isoString: string) =&gt; {\n    try {\n      const d = new Date(isoString);\n      return d.toLocaleDateString(&#039;en-US&#039;, { month: &#039;short&#039;, day: &#039;numeric&#039;, year: &#039;numeric&#039; });\n</code></pre>"
